import sys
from collections import defaultdict

sys.setrecursionlimit(400000)

def dfs(v, p):
    size[v] = 1
    for u in graph[v]:
        if u == p:
            continue
        dfs(u, v)
        size[v] += size[u]

def is_centroid(v, p, total_size):
    if total_size - size[v] > total_size // 2:
        return False
    for u in graph[v]:
        if u == p:
            continue
        if size[u] > total_size // 2:
            return False
    return True

n = int(input())
graph = defaultdict(list)

for _ in range(n - 1):
    u, v = map(int, input().split())
    graph[u].append(v)
    graph[v].append(u)

size = [0] * (n + 1)
dfs(1, -1)

centroid_candidates = [0] * (n + 1)

for v in range(1, n + 1):
    for u in graph[v]:
        if size[u] > size[v]:
            total_size = size[u]
        else:
            total_size = n - size[v]
        if is_centroid(v, u, total_size):
            centroid_candidates[v] = 1
            break

print(' '.join(map(str, centroid_candidates[1:])))
